using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class CathedralChecks {
 static void Require(bool value,string message){if(!value)throw new Exception(message);}
 [MenuItem("BWVR/Verify cathedral model")]
 public static void VerifyModel(){var c=new CathedralState();var resources=new ResourceState{wood=36};for(int k=0;k<5;k++){
  for(int n=0;n<39;n++)c.Advance(.5f,1);Require(!c.Building,"Brief faith authorized cathedral");c.Advance(.5f,1);Require(c.authorized==k+1,"Faith failed to authorize stage");Require(!c.Build(.5f),"Free construction without timber");float spent=0;
  while(c.Remaining>0){resources.wood=36;float amount=c.Collect(resources,0,3);spent+=amount;Require(amount>0&&resources.wood==36-amount,"Material payment incorrect");Require(c.Collect(resources,0,3)==0,"Duplicate cargo collection");var save=JsonUtility.FromJson<CathedralState>(JsonUtility.ToJson(c));Require(save.Valid()&&save.cargo[0]==amount,"Transit timber not persistent");c.Deliver(0);c.Deliver(0);}
  Require(spent==CathedralState.Timber[k]&&c.Valid(),"Delivery duplicated or lost timber");for(int n=0;n<(int)CathedralState.Labor[k]*2-1;n++)Require(!c.Build(.5f),"Construction finished without enough labor");Require(c.Build(.5f)&&c.level==k+1&&c.Valid(),"Labor failed to finish stage");c.Advance(1,0);Require(c.level==k+1,"Lost completed building when faith fell");
 }
 string before=JsonUtility.ToJson(c);c.Advance(float.NaN,1);c.Build(float.PositiveInfinity);Require(before==JsonUtility.ToJson(c),"Invalid time mutated state");Require(JsonUtility.FromJson<SliceState>("{\"version\":1,\"seconds\":180,\"water\":52,\"crops\":66,\"trust\":20,\"care\":0.25}").Valid(),"Legacy save invalid");c.cargo[0]=1;Require(!c.Valid(),"Impossible cargo accepted");Debug.Log("BWVR_CATHEDRAL_MODEL_PASS");}
 [MenuItem("BWVR/Verify cathedral runtime (Play mode)")]
 public static void VerifyRuntime(){Require(EditorApplication.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);var temple=slice.GetComponentInChildren<VillageCathedral>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var jobs=world.Gatherers.Select(g=>g.GetComponent<VillagerRoutine>()).ToArray();var positions=jobs.Select(j=>j.transform.position).ToArray();var rotations=jobs.Select(j=>j.transform.rotation).ToArray();god.Interrupt("Cathedral QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};field.SetValue(slice,test);
  try{world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();temple.ResetWorld();test.Cathedral.authorized=1;test.Resources.wood=12;foreach(var job in jobs){job.GetComponent<VillagerSocial>().ResetTask();job.GetComponent<VillagerExploration>().ResetTask();job.GetComponent<VillagerBlockPlay>().ResetTask();job.ResetTask();}var worker=jobs[0];Require(temple.Tick(worker,.1f)&&worker.BuildingCathedral,"Builder failed to acquire ownership");worker.transform.position=world.StoreApproach;worker.GetComponent<IslandNavigator>().ResetRoute();temple.Tick(worker,.1f);Require(test.Resources.wood==9&&test.Cathedral.cargo[0]==3,"Store pickup not charged exactly once");worker.GetComponent<CarryItem>().held=true;Require(!temple.Tick(worker,.1f)&&!worker.BuildingCathedral&&test.Cathedral.cargo[0]==3,"Player pickup lost cargo or ownership");worker.GetComponent<CarryItem>().held=false;Require(temple.Tick(worker,.1f),"Cargo did not resume");var points=(Vector3[])typeof(VillageCathedral).GetField("workAt",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(temple);worker.transform.position=points[0];worker.GetComponent<IslandNavigator>().ResetRoute();temple.Tick(worker,.1f);Require(test.Cathedral.timber==3&&test.Cathedral.cargo[0]==0,"Timber was not delivered");test.paused=true;string saved=JsonUtility.ToJson(test);temple.Advance(.5f);temple.Tick(worker,.5f);Require(saved==JsonUtility.ToJson(test),"Paused cathedral progressed");test.paused=false;test.Religion.fanatic=true;Require(!temple.Tick(worker,.1f)&&temple.Workers==0,"Fanaticism retained productive builder");test.Religion.fanatic=false;test.Cathedral.timber=6;test.Cathedral.work=CathedralState.Labor[0]-.1f;Require(temple.Tick(worker,.1f)==false&&test.Cathedral.level==1,"Completed construction did not switch model");temple.Advance(.1f);Require(temple.GetComponentsInChildren<Renderer>().Any(r=>r.gameObject.name=="Stone and roof"),"Built shrine has no art");var copy=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(copy.Valid()&&copy.Cathedral.level==1&&copy.Cathedral.sited,"Cathedral save invalid");test.Cathedral.authorized=2;temple.Tick(worker,.1f);temple.ResetWorld();Require(temple.Workers==0&&!worker.BuildingCathedral,"Reload kept transient worker");Debug.Log("BWVR_CATHEDRAL_RUNTIME_PASS");
  }finally{foreach(var j in jobs)j.GetComponent<CarryItem>().held=false;field.SetValue(slice,original);temple.ResetWorld();world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();for(int i=0;i<jobs.Length;i++){jobs[i].transform.SetPositionAndRotation(positions[i],rotations[i]);jobs[i].GetComponent<IslandNavigator>().ResetRoute();}god.NewSeason();}
 }
}
}
